import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"震下離上 噬嗑：","description":"京氏易傳 - 震下離上 噬嗑：","frontmatter":{"title":"震下離上 噬嗑：","description":"京氏易傳 - 震下離上 噬嗑："},"headers":[],"relativePath":"classics/jingshi/047.md","filePath":"classics/jingshi/047.md"}'),r={name:"classics/jingshi/047.md"};function l(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"震下離上-噬嗑",tabindex:"-1"},[i("震下離上 噬嗑： "),e("a",{class:"header-anchor",href:"#震下離上-噬嗑","aria-label":"Permalink to “震下離上 噬嗑：”"},"​")],-1),e("p",null,"柔來文剛，積氣居中，陰道明白，動見文明。雷電合，分威光，而噬嗑也。《易》曰：“頤中有物，曰噬嗑”。陰陽分中，動而明；【象雷電也。】物有不齊，齧而噬。（虎易注：齧為（齧）的繁體字，讀音：nie，四聲。意為：啃或咬。）吉凶之道，象於五行。順則吉，逆則兇。火木合卦配升降。與離為飛伏。【己未土，辛巳火。】六五居尊，應六二大夫。",-1),e("p",null,"建始丙午至辛亥，【芒種，小雪。】積算起辛亥至庚戌，週而復始。火土入離震。【分火土二位入噬嗑卦，起積算爻，推配星辰，歲月日時，進退吉凶。】",-1),e("p",null,"五星從位起鎮星，【土星入卦。】女宿從位降己未土，【二十八宿，分女宿入卦六五己未土也。】分氣候二十八。【從二十八位數起八卦，算吉凶。】",-1),e("p",null,"火居水上，陽中見陰，陽雜氣渾而溷，（虎易注：溷：讀音：hun，四聲。意為：混濁。）吉凶適變，隨時見也。返復陰，遊魂入卦。【降下九四陽入陰。】五行進退，始終之道，斯可驗矣。升降六爻，極返終，下降山雷頤卦。",-1)])])}const _=s(r,[["render",l]]);export{u as __pageData,_ as default};
